+    });

     auto sortCallback = [this] {
         if (m_SortingMode == SortingMode::Random && !m_usedInConfig) {
@@ -76,6 +88,12 @@ QHash<int, QByteArray> SlideFilterModel::roleNames() const
 bool SlideFilterModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
 {
     auto index = sourceModel()->index(source_row, 0, source_parent);
+    if (m_dynamicOnly) {
+        const QStringList selectors = index.data(ImageRoles::SelectorsRole).toStringList();
+        if (!selectors.contains(m_dynamicMode == DynamicMode::Mode::DayNight ? QStringLiteral("day-night") : QStringLiteral("dark-light"))) {
+            return false;
+        }
+    }
     return m_usedInConfig || index.data(ImageRoles::ToggleRole).toBool();
 }

